                /**
                 * Podání soupisky
                 *
                 * @returns {JQuery.Promise<any>} promise s operací
                 */
                podani() {
                    // otevření prázdného detailu - vyvolá se podání
                    return this.openDetail(this);
                }
                /**
                 * Zobrazení detailu soupisky
                 *
                 * @returns {JQuery.Promise<any>} promise s operací
                 */
                detail() {
                    // aktuální vybraná položka
                    const aktRadek = Gordic.Eko.Grid.currentRow(this.element.find(".SeznamFuc.ggrid"));
                    if (aktRadek && !(aktRadek instanceof jQuery)) {
                        // otevření detailu aktuální vybrané položky
                        return this.openDetail(this, aktRadek);
                    }
                    else
                        return $.Deferred().reject().promise();
                }
                /**
                 * Zobrazení detailu existující nebo podání nové soupisky
                 *
                 * @param {GContent} content content
                 * @param {Gordic.Fuc.Interface.GSoupiskaDto} [row] aktuální řádek (pro zobrazení detailu) nebo null (pro podání)
                 * @param {FucGrid.openDetailWizardParams} [wizard] parametry průvodce (v případě volání detailu z průvodce)
                 * @returns {JQuery.Promise<any>} promise s operací
                 */
                openDetail(content, row, wizard) {
                    let that = this;
                    // zásobník změněných záznamů
                    let changedRows = [];
                    // GPC s knihou z aktuálního záznamu
                    const newGpc = (row ? Gordic.Eko.Utils.createBookGpc(content /*this*/.gpc, row.ixp_den) : content /*this*/.gpc);
                    // otevření detailu
                    let $detailWindow = content.navigate(["Gordic.Fuc.WebClient.GDetailSoupisky", { gpc: newGpc, gridRemoteControl: new Gordic.Components.GridRC(wizard?.grid ?? that.element.find(".SeznamFuc.ggrid")) }], {
                        ID: 'DetailSoupisky#',
                        Ixp: row?.ixp,
                        //IxpDen: row?.ixp_den ?? that.getIxpDen()/*that.IxpDen*/,
                        // TODO: musí tady být || null?
                        //SubradaDen: this.ekoBook?.subrada || null/*that.SubradaDen*/,
                        //AktSubradyDen: this.ekoBook?.akt_subrady || null/*that.AktSubradyDen*/
                    });
                    // obsluha aktivní operace na detailu
                    $.content($detailWindow).on(WebClient.FucDetail.triggerChange, (retVal) => {
                        if (retVal?.data?.ixp) {
                            // přidání do seznamu záznamů k občerstvení
                            if (changedRows.indexOf(retVal.data.ixp) < 0)
                                changedRows.push(retVal.data.ixp);
                        }
                    });
                    // obsluha ukončení okna
                    $detailWindow.on("closed", (retVal) => {
                        // nastavení fokusu (jen pokud není průvodce)
                        if (!wizard)
                            that.element.find(".SeznamFuc.ggrid").ggrid("focus");
                        // aktualizace změněných záznamů (v hlavním seznamu i případně v průvodci)
                        if (changedRows?.length > 0) {
                            // nastavení aktivní operace
                            if (wizard?.setActiveOperation && typeof (wizard.setActiveOperation) === "function") {
                                wizard.setActiveOperation();
                            }
                            // aktualizace základního gridu
                            that.view.requestData({ filters: { ixp: changedRows }, onlyPKWithoutFilters: true }, { updateMode: "update" })
                                .done(function () {
                                // nastavení aktuálního řádku
                                if (retVal?.returnValue?.ixp) {
                                    that.element.find(".SeznamFuc.ggrid").ggrid("activeRow", { ixp: retVal?.returnValue?.ixp });
                                }
                                // v případě průvodce i aktualizace gridu v průvodci
                                if (wizard) {
                                    WebClient.FucWizard.reloadRows((rq) => { return that.isl.FinPohybSoupiska.list(rq); }, { ixp: changedRows }, wizard.grid)
                                        .then(function () {
                                        if (wizard && wizard.refreshAndCheckDataAction != undefined && typeof (wizard.refreshAndCheckDataAction) === "function") {
                                            return wizard.refreshAndCheckDataAction();
                                        }
                                    });
                                }
                            });
                        }
                    });
                    return $detailWindow.createDialogPromise();
                }
                /**
                 * Zobrazení detailu soupisky v nové zálozce
                 *
                 * @returns {JQuery.Promise<any>} promise s operací
                 */
                detailDoZalozky() {
                    // aktuální vybraná položka
                    const aktRadek = Gordic.Eko.Grid.currentRow(this.element.find(".SeznamFuc.ggrid"));
                    if (aktRadek && !(aktRadek instanceof jQuery)) {
                        // otevření detailu aktuální vybrané položky v nové záložce
                        return WebClient.FucUtils.openDetailInOtherTab(Fuc.Globals.Enums.TypAg.FUC, aktRadek.ixp);
                    }
                    else
                        return $.Deferred().reject().promise();
                }
                /**
                 * Účtování pohybů soupisek
                 *
                 * @param {boolean} vse účtovat všechny pohyby v seznamu (false = jen vybrané, true = všechny)
                 * @param {boolean} async pustit jako asynchronní úlohu (true = ano, false = ne, standardně přes průvodce)
                 * @param {Gordic.Fuc.Globals.Enums.TypUct} [typUctovani] typ účtování
                 * @returns {JQuery.Promise<any>} promise s operací
                 */
                uctovani(vse, async, typUctovani) {
                    let that = this;
                    // kontrola na běžící účtování
                    if (WebClient.FucUtils.isAsyncUctovaniRunning()) {
                        // TODO: ještě nastavit průběh na akci?
                        return that.dialogs.error("jres:24100210", //RC 24100210 : Účtování
                        "jres:24100417") //RC 24100417 : Aktuálně není možné soupisky pohybů zaúčtovat, protože probíhá jiné účtování
                            .createDialogPromise(() => false);
                    }
                    const $grid = this.element.find(".SeznamFuc.ggrid");
                    if ($grid !== null) {
                        // zjištění sooupisek k účtování
                        let soupisky = [];
                        let vsechnySoupisky = vse;
                        const currentFilter = this.$filterForm.gfilterpanel("getConfirmedData");
                        // pro účtování všeho musí být známy filtry
                        if (currentFilter === null)
                            vsechnySoupisky = false;
                        if (!vsechnySoupisky) {
                            // zaškrtnuté položky
                            const zaskrRadky = this.element.find(".SeznamFuc.ggrid").ggrid("getSelection");
                            if (zaskrRadky !== null && zaskrRadky.length > 0) {
                                // redukce záznamů jen na hodnoty primárního klíče (je zbytečné předávat ostatní údaje a navíc to při velkém počtu záznamů padalo)
                                soupisky = that.getRowsForUctovani(zaskrRadky);
                            }
                        }
                        // spuštění účtování
                        if ((soupisky ?? []).length > 0 || vsechnySoupisky) {
                            // vložení označených pohybů do pracovní tabulky
                            if (vsechnySoupisky) {
                                return this.call("VlozitPohybyVsechSoupisekDoPracSeznamu", { filters: currentFilter })
                                    .then(function (ikc) {
                                    // účtování
                                    if (async)
                                        return that.uctovaniAsync(ikc, typUctovani);
                                    else
                                        return that.uctovaniWizard(ikc, typUctovani);
                                });
                            }
                            else {
                                return this.call("VlozitPohybySoupisekDoPracSeznamu", { zaznamy: soupisky })
                                    .then(function (ikc) {
                                    // účtování
                                    if (async)
                                        return that.uctovaniAsync(ikc, typUctovani);
                                    else
                                        return that.uctovaniWizard(ikc, typUctovani);
                                });
                            }
                        }
                        else
                            return $.Deferred().reject().promise();
                    }
                    else
                        return $.Deferred().reject().promise();
                }
                /**
                 * Pomocná metoda pro úpravu seznamu pohybů pro účtování (při volání z metody uctovani)
                 *
                 * @param {Gordic.Fuc.Interface.GPohybDto[]} rows pohyby, které se mají účtovat
                 * @returns {Gordic.Fuc.Interface.GPohybDto[]} upravená (redukovaná) data pohybů pro účtování
                 */
                getRowsForUctovani(rows) {
                    // TODO: neudělat z toho společnou metodu? obdobná je použita i v soupiskách
                    const pkSplit = (this.PrimaryKey ?? "ixp").split(",");
                    return rows.map(zaznam => {
                        let zaznamPK = {};
                        pkSplit.forEach(key => { zaznamPK[key] = zaznam[key]; });
                        return zaznamPK;
                    });
                }
